import java.util.Scanner;
public class Primes {
  static boolean isPrime(int n) {
    if (n < 2) return false;
    for (int i = 2; i * i <= n; i++)
      if (n % i == 0) return false;
    return true;
  }
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int m = sc.nextInt(), n = sc.nextInt();
    if (m > n) {
      int t = m; m = n; n = t;
    }
    int count = 0;
    for (int i = m; i <= n; i++) {
      if (isPrime(i)) {
        if (count % 5 != 0)
          System.out.print(" ");
        System.out.print(i);
        count++;
        if (count % 5 == 0) System.out.println();
      }
    }
    if (count % 5 != 0) System.out.println();
    System.out.println("共 " + count + " 个");
  }
}

import java.util.Scanner;
public class Scores {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int max = -1, min = 101, sum = 0;
    int good = 0, pass = 0, fail = 0;
    for (int i = 0; i < n; i++) {
      int s = sc.nextInt();
      sum += s;
      if (s > max) max = s;
      if (s < min) min = s;
      if (s >= 90) good++;
      else if (s >= 60) pass++;
      else fail++;
    }
    double avg = (double) sum / n;
    System.out.println("最高分：" + max);
    System.out.println("最低分：" + min);
    System.out.printf("平均分：%.1f%n", avg);
    System.out.println("优秀 " + good + " 人，及格 "
        + pass + " 人，不及格 " + fail + " 人");
  }
}

import java.util.Scanner;
public class Capital {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    String line = sc.nextLine().trim();
    if (line.length() == 0) {
      System.out.println("单词数：0");
      return;
    }
    String[] words = line.split("\\s+");
    StringBuffer sb = new StringBuffer();
    for (int i = 0; i < words.length; i++) {
      String w = words[i];
      char c = Character.toUpperCase(w.charAt(0));
      sb.append(c).append(w.substring(1));
      if (i < words.length - 1) sb.append(" ");
    }
    System.out.println("单词数：" + words.length);
    System.out.println(sb);
  }
}

import java.util.Scanner;
public class Palindrome {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    String s = sc.nextLine();
    StringBuffer r = new StringBuffer(s);
    System.out.println("反转：" + r.reverse());
    StringBuffer t = new StringBuffer();
    for (int i = 0; i < s.length(); i++) {
      char c = s.charAt(i);
      if (Character.isLetterOrDigit(c))
        t.append(Character.toLowerCase(c));
    }
    String a = t.toString();
    String b = t.reverse().toString();
    if (a.equals(b))
      System.out.println("是回文");
    else
      System.out.println("不是回文");
  }
}

import java.util.Scanner;
public class DayOfYear {
  static boolean isLeap(int y) {
    return (y % 4 == 0 && y % 100 != 0)
        || y % 400 == 0;
  }
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int y = sc.nextInt(), m = sc.nextInt();
    int d = sc.nextInt();
    int[] days = {31, 28, 31, 30, 31, 30,
                  31, 31, 30, 31, 30, 31};
    if (isLeap(y)) days[1] = 29;
    if (m < 1 || m > 12 || d < 1
        || d > days[m - 1]) {
      System.out.println("日期不合法");
      return;
    }
    int total = d;
    for (int i = 0; i < m - 1; i++)
      total += days[i];
    System.out.println("第 " + total + " 天");
  }
}

import java.util.Scanner;
class BankException extends Exception {
  BankException(String m) { super(m); }
}
class Account {
  private double balance;
  public Account(double b) { balance = b; }
  public double getBalance() { return balance; }
  void deposit(double x) throws BankException {
    if (x <= 0)
      throw new BankException("金额无效");
    balance += x;
  }
  void withdraw(double x) throws BankException {
    if (x <= 0)
      throw new BankException("金额无效");
    if (x > balance)
      throw new BankException("余额不足");
    balance -= x;
  }
}
public class TestAccount {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    Account a = new Account(100);
    while (true) {
      String op = sc.next();
      if (op.equals("q")) break;
      double amt = sc.nextDouble();
      try {
        if (op.equals("d")) a.deposit(amt);
        else a.withdraw(amt);
      } catch (BankException e) {
        System.out.println(e.getMessage());
        continue;
      }
      System.out.println("余额：" + a.getBalance());
    }
  }
}

abstract class Employee {
  protected String name;
  Employee(String n) { name = n; }
  abstract double earnings();
  public String toString() {
    return String.format("%s：%.2f", name,
        earnings());
  }
}
class Salaried extends Employee {
  private double salary;
  Salaried(String n, double s) {
    super(n); salary = s;
  }
  double earnings() { return salary; }
}
class Hourly extends Employee {
  private double wage, hours;
  Hourly(String n, double w, double h) {
    super(n);
    wage = w; hours = h;
  }
  double earnings() {
    if (hours <= 40) return wage * hours;
    return wage * 40 + wage * 1.5 * (hours - 40);
  }
}
public class Payroll {
  public static void main(String[] args) {
    Employee[] e = { new Salaried("张三", 5000),
        new Hourly("李四", 50, 40),
        new Hourly("王五", 50, 45) };
    double total = 0;
    for (int i = 0; i < e.length; i++) {
      System.out.println(e[i]);
      total += e[i].earnings();
    }
    System.out.printf("工资总额：%.2f%n", total);
  }
}

import java.util.*;
class Student implements Comparable<Student> {
  int id, score;
  String name;
  Student(int id, String name, int score) {
    this.id = id;
    this.name = name;
    this.score = score;
  }
  public int compareTo(Student o) {
    if (score != o.score) return o.score - score;
    return id - o.id;
  }
}
public class Rank {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    Student[] a = new Student[n];
    for (int i = 0; i < n; i++) {
      int id = sc.nextInt();
      String name = sc.next();
      a[i] = new Student(id, name, sc.nextInt());
    }
    Arrays.sort(a);
    for (int i = 0; i < n; i++) {
      Student s = a[i];
      System.out.println((i + 1) + " " + s.id
          + " " + s.name + " " + s.score);
    }
  }
}

import java.util.*;
class Item {
  String name;
  double price;
  int qty;
  Item(String n, double p, int q) {
    name = n;
    price = p;
    qty = q;
  }
  double subtotal() { return price * qty; }
}
public class Cart {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    Vector<Item> v = new Vector<Item>();
    while (true) {
      String n = sc.next();
      if (n.equals("end")) break;
      double p = sc.nextDouble();
      int q = sc.nextInt();
      v.add(new Item(n, p, q));
    }
    double total = 0;
    for (int i = 0; i < v.size(); i++) {
      Item it = v.get(i);
      System.out.printf("%s：%.2f%n", it.name,
          it.subtotal());
      total += it.subtotal();
    }
    double pay = total;
    if (total >= 200) pay = total * 0.9;
    System.out.printf("总金额：%.2f%n", total);
    System.out.printf("实付：%.2f%n", pay);
  }
}

import java.util.Scanner;
class Fraction {
  private int num, den;
  public Fraction(int n, int d) {
    if (d == 0)
      throw new IllegalArgumentException(
          "分母不能为 0");
    if (d < 0) { n = -n; d = -d; }
    int g = gcd(Math.abs(n), d);
    num = n / g;
    den = d / g;
  }
  static int gcd(int a, int b) {
    return b == 0 ? a : gcd(b, a % b);
  }
  public Fraction add(Fraction f) {
    return new Fraction(num * f.den + f.num * den,
        den * f.den);
  }
  public String toString() {
    return den == 1 ? "" + num : num + "/" + den;
  }
}
public class TestFraction {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int a = sc.nextInt(), b = sc.nextInt();
    int c = sc.nextInt(), d = sc.nextInt();
    try {
      Fraction f1 = new Fraction(a, b);
      Fraction f2 = new Fraction(c, d);
      System.out.println(f1 + " + " + f2 + " = "
          + f1.add(f2));
    } catch (IllegalArgumentException e) {
      System.out.println(e.getMessage());
    }
  }
}

import java.awt.*;
import java.awt.event.*;
import javax.swing.*;
public class Calc extends JFrame
    implements ActionListener {
  JTextField t1 = new JTextField(6);
  JTextField t2 = new JTextField(6);
  JLabel result = new JLabel("结果：");
  public Calc() {
    super("计算器");
    setLayout(new FlowLayout());
    add(t1); add(t2); add(result);
    for (char c : "+-*/".toCharArray()) {
      JButton b = new JButton("" + c);
      b.addActionListener(this);
      add(b);
    }
    setDefaultCloseOperation(EXIT_ON_CLOSE);
    setSize(360, 120); setVisible(true);
  }
  public void actionPerformed(ActionEvent e) {
    String op = e.getActionCommand();
    try {
      double a = Double.parseDouble(t1.getText());
      double b = Double.parseDouble(t2.getText());
      double r = a / b;
      if (op.equals("+")) r = a + b;
      if (op.equals("-")) r = a - b;
      if (op.equals("*")) r = a * b;
      String s = String.format("结果：%.2f", r);
      if (op.equals("/") && b == 0) s = "除数不能为 0";
      result.setText(s);
    } catch (NumberFormatException ex) {
      result.setText("请输入数字");
    }
  }
  public static void main(String[] args) {
    new Calc();
  }
}

import java.awt.*;
import java.awt.event.*;
import javax.swing.*;
public class Login extends JFrame
    implements ActionListener {
  JTextField user = new JTextField(10);
  JPasswordField pwd = new JPasswordField(10);
  JButton ok = new JButton("登录");
  JButton reset = new JButton("重置");
  JLabel msg = new JLabel();
  int fails = 0;
  public Login() {
    setLayout(new GridLayout(4, 2, 5, 5));
    add(new JLabel("用户名：")); add(user);
    add(new JLabel("密码：")); add(pwd);
    add(ok); add(reset); add(msg);
    ok.addActionListener(this);
    reset.addActionListener(this);
    setDefaultCloseOperation(EXIT_ON_CLOSE);
    setSize(280, 160); setVisible(true);
  }
  public void actionPerformed(ActionEvent e) {
    if (e.getSource() == reset) {
      user.setText(""); pwd.setText("");
      msg.setText("");
      return;
    }
    String u = user.getText().trim();
    String p = new String(pwd.getPassword());
    if (u.equals("admin") && p.equals("123456")) {
      msg.setText("登录成功"); fails = 0;
    } else if (++fails >= 3) {
      msg.setText("错误 3 次，已锁定");
      ok.setEnabled(false);
    } else msg.setText("用户名或密码错误");
  }
  public static void main(String[] args) {
    new Login();
  }
}

import java.awt.*;
import java.awt.event.*;
import javax.swing.*;
public class Register extends JFrame
    implements ActionListener {
  JTextField name = new JTextField(8);
  JRadioButton male = new JRadioButton("男", true);
  JRadioButton female = new JRadioButton("女");
  JCheckBox[] hobby = { new JCheckBox("阅读"),
      new JCheckBox("运动"), new JCheckBox("音乐") };
  String[] cities = {"南京", "苏州", "无锡"};
  JComboBox<String> cb = new JComboBox<>(cities);
  JTextArea info = new JTextArea(4, 20);
  public Register() {
    setLayout(new FlowLayout());
    add(new JLabel("姓名")); add(name);
    ButtonGroup g = new ButtonGroup();
    g.add(male); g.add(female);
    add(male); add(female);
    for (JCheckBox c : hobby) add(c);
    JButton ok = new JButton("提交");
    ok.addActionListener(this);
    add(cb); add(ok); add(info);
    setDefaultCloseOperation(EXIT_ON_CLOSE);
    setSize(300, 240); setVisible(true);
  }
  public void actionPerformed(ActionEvent e) {
    String h = "";
    for (JCheckBox c : hobby)
      if (c.isSelected()) h += c.getText() + " ";
    if (h.equals("")) h = "无";
    String sex = male.isSelected() ? "男" : "女";
    info.setText("姓名：" + name.getText()
        + "\n性别：" + sex + "\n爱好：" + h.trim()
        + "\n城市：" + cb.getSelectedItem());
  }
  public static void main(String[] args) {
    new Register();
  }
}

import java.awt.*;
import java.awt.event.*;
import javax.swing.*;
public class Editor extends JFrame
    implements ActionListener {
  JTextArea area = new JTextArea();
  JLabel status = new JLabel("就绪");
  public Editor() {
    super("文本编辑");
    JMenuBar bar = new JMenuBar();
    JMenu edit = new JMenu("编辑");
    String[] items = {"大写", "小写", "统计", "清空"};
    for (String s : items) {
      JMenuItem mi = new JMenuItem(s);
      mi.addActionListener(this);
      edit.add(mi);
    }
    bar.add(edit);
    setJMenuBar(bar);
    JScrollPane sp = new JScrollPane(area);
    add(sp, BorderLayout.CENTER);
    add(status, BorderLayout.SOUTH);
    setDefaultCloseOperation(EXIT_ON_CLOSE);
    setSize(360, 240);
    setVisible(true);
  }
  public void actionPerformed(ActionEvent e) {
    String op = e.getActionCommand();
    String t = area.getText();
    if (op.equals("大写")) t = t.toUpperCase();
    else if (op.equals("小写")) t = t.toLowerCase();
    else if (op.equals("清空")) t = "";
    else status.setText("字符数：" + t.length());
    area.setText(t);
  }
  public static void main(String[] args) {
    new Editor();
  }
}

import java.awt.*;
import java.awt.event.*;
import javax.swing.*;
public class Guess extends JFrame
    implements ActionListener {
  JTextField input = new JTextField(5);
  JLabel tip = new JLabel("请输入 1～100 的整数");
  int secret = (int) (Math.random() * 100) + 1;
  int count = 0;
  public Guess() {
    super("猜数字");
    setLayout(new FlowLayout());
    JButton btn = new JButton("猜");
    btn.addActionListener(this);
    add(input); add(btn); add(tip);
    setDefaultCloseOperation(EXIT_ON_CLOSE);
    setSize(360, 100); setVisible(true);
  }
  public void actionPerformed(ActionEvent e) {
    String s = input.getText().trim();
    int n;
    try { n = Integer.parseInt(s); }
    catch (NumberFormatException ex) { n = 0; }
    if (n < 1 || n > 100) {
      tip.setText("请输入 1～100 的整数");
      return;
    }
    count++;
    if (n > secret) tip.setText("大了");
    else if (n < secret) tip.setText("小了");
    else {
      tip.setText("猜对了！共猜了 " + count + " 次");
      secret = (int) (Math.random() * 100) + 1;
      count = 0;
    }
  }
  public static void main(String[] args) {
    new Guess();
  }
}
